// run with: bare lib/node_modules/drive-loader/test.js (needs bare 1.32+)
const Corestore = require('corestore')
const RAM = require('random-access-memory')
const b4a = require('b4a')
const { create_autodrive } = require('autodrive')
const drive_loader = require('./')

let failed = 0
main().then(done)

async function main () {
  const drive = create_autodrive({ store: new Corestore(RAM).namespace('app') })
  await drive.ready()
  // a small app: main.js requires a file next to it, a json file and one module from outside the drive
  await drive.put('/main.js', b4a.from("const greet = require('./lib/greet.js')\nconst { name } = require('./config.json')\nmodule.exports = greet(name) + ' ' + require('b4a').toString(require('b4a').from('v1'))"))
  await drive.put('/lib/greet.js', b4a.from("module.exports = name => 'hello ' + name"))
  await drive.put('/config.json', b4a.from('{ "name": "lupay" }'))
  check('runs an app made of several files straight from an autodrive', await drive_loader({ drive, file: '/main.js', builtins: { b4a } }) === 'hello lupay v1')
  // npm dependencies can live inside the drive under /node_modules
  await drive.put('/node_modules/shout/package.json', b4a.from('{ "name": "shout", "main": "lib/index.js" }'))
  await drive.put('/node_modules/shout/lib/index.js', b4a.from("module.exports = text => text.toUpperCase() + '!'"))
  await drive.put('/loud.js', b4a.from("module.exports = require('shout')('hi')"))
  check('finds packages in the drive /node_modules', await drive_loader({ drive, file: '/loud.js' }) === 'HI!')
  const signed = drive.base.view.drive.core.getBackingCore().session
  const length = await wait_for_signed(drive, signed)
  await drive.put('/main.js', b4a.from("module.exports = 'v2'"))
  check('runs the new version after an update', await drive_loader({ drive, file: '/main.js', builtins: { b4a } }) === 'v2')
  const pinned = drive.base.view.drive.checkout(length)
  check('runs the old version from a checkout at the pinned length', await drive_loader({ drive: pinned, file: '/main.js', builtins: { b4a } }) === 'hello lupay v1')
  await pinned.close()
  await drive.put('/fs.js', b4a.from("module.exports = require('bare-fs')"))
  // bare-fs is neither in the drive nor in builtins, require() is sync and a drive can only answer async, so it cant be loaded
  check('refuses modules that are not in builtins', await fails(drive_loader({ drive, file: '/fs.js', builtins: { b4a } }), 'UNEXPECTED_PROMISE'))
  await drive.put('/sneaky.js', b4a.from("import('bare-fs')\nmodule.exports = 1"))
  check('refuses dynamic import()', await fails(drive_loader({ drive, file: '/sneaky.js' }), 'SyntaxError'))
  check('refuses files that are not in the drive', await fails(drive_loader({ drive, file: '/nope.js' }), 'MODULE_NOT_FOUND'))
  await drive.close()
}

/***************************************
HELPERS
***************************************/
function check (name, ok) {
  console.log(`${ok ? 'ok' : 'not ok'} ${name}`)
  if (!ok) failed++
}

function done () {
  console.log(failed ? `${failed} failed` : 'all good')
  if (failed) throw new Error('drive-loader tests failed')
}

function fails (promise, reason) { return promise.then(() => false, err => (err.code || err.name) === reason) }

// the signed core lags a bit behind the latest writes, wait until it caught up
async function wait_for_signed (drive, signed) {
  while (signed.length < drive.base.view.drive.core.length) {
    await drive.base.update()
    await new Promise(resolve => setTimeout(resolve, 50))
  }
  return signed.length
}
